    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endCVP(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // COVERAGE_ID
        $builder->required($o, 34);  // VERTEX_LONGITUDE_DEG
        $builder->required($o, 36);  // VERTEX_LATITUDE_DEG
        $builder->required($o, 44);  // RING_OFFSETS
        $builder->required($o, 46);  // RING_POLYGON_INDEXES
        $builder->required($o, 48);  // RING_ROLES
        $builder->required($o, 74);  // CONTRIBUTING_EMITTERS
        $builder->required($o, 90);  // PROVENANCE
        return $o;
    }

    public static function finishCVPBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$CVP");
    }
}
